using Xunit;
using ContosoUniversity.Models;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        // Concrete subclass for testing abstract Person
        private class TestPerson : Person { }

        [Fact]
        public void FullName_BothNamesSet_ReturnsLastCommaFirst()
        {
            var person = new TestPerson { LastName = "Smith", FirstMidName = "John" };

            Assert.Equal("Smith, John", person.FullName);
        }

        [Fact]
        public void FullName_SingleCharNames_FormatsCorrectly()
        {
            var person = new TestPerson { LastName = "S", FirstMidName = "J" };

            Assert.Equal("S, J", person.FullName);
        }

        [Fact]
        public void FullName_WithSpacesInNames_PreservesSpaces()
        {
            var person = new TestPerson { LastName = "Van Buren", FirstMidName = "Mary Jane" };

            Assert.Equal("Van Buren, Mary Jane", person.FullName);
        }

        [Fact]
        public void ID_DefaultsToZero()
        {
            var person = new TestPerson();

            Assert.Equal(0, person.ID);
        }
    }

    public class StudentTests
    {
        [Fact]
        public void Student_InheritsFromPerson_HasFullName()
        {
            var student = new Student
            {
                LastName = "Alexander",
                FirstMidName = "Carson",
                EnrollmentDate = new System.DateTime(2020, 9, 1)
            };

            Assert.Equal("Alexander, Carson", student.FullName);
            Assert.Equal(new System.DateTime(2020, 9, 1), student.EnrollmentDate);
        }

        [Fact]
        public void Student_Enrollments_InitiallyNull()
        {
            var student = new Student();

            Assert.Null(student.Enrollments);
        }
    }

    public class InstructorTests
    {
        [Fact]
        public void Instructor_InheritsFromPerson_HasFullName()
        {
            var instructor = new Instructor
            {
                LastName = "Fakhouri",
                FirstMidName = "Fadi",
                HireDate = new System.DateTime(2002, 7, 6)
            };

            Assert.Equal("Fakhouri, Fadi", instructor.FullName);
            Assert.Equal(new System.DateTime(2002, 7, 6), instructor.HireDate);
        }

        [Fact]
        public void Instructor_CourseAssignments_InitiallyNull()
        {
            var instructor = new Instructor();

            Assert.Null(instructor.CourseAssignments);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_WhenRequestIdIsSet_ReturnsTrue()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_WhenRequestIdIsNull_ReturnsFalse()
        {
            var model = new ErrorViewModel { RequestId = null };

            Assert.False(model.ShowRequestId);
        }

        [Fact]
        public void ShowRequestId_WhenRequestIdIsEmpty_ReturnsFalse()
        {
            var model = new ErrorViewModel { RequestId = "" };

            Assert.False(model.ShowRequestId);
        }
    }

    public class EnrollmentTests
    {
        [Fact]
        public void Enrollment_Grade_CanBeNull()
        {
            var enrollment = new Enrollment
            {
                EnrollmentID = 1,
                CourseID = 100,
                StudentID = 1,
                Grade = null
            };

            Assert.Null(enrollment.Grade);
            Assert.Equal(100, enrollment.CourseID);
            Assert.Equal(1, enrollment.StudentID);
        }

        [Theory]
        [InlineData(Grade.A)]
        [InlineData(Grade.B)]
        [InlineData(Grade.C)]
        [InlineData(Grade.D)]
        [InlineData(Grade.F)]
        public void Enrollment_AllGradeValues_Settable(Grade grade)
        {
            var enrollment = new Enrollment { Grade = grade };

            Assert.Equal(grade, enrollment.Grade);
        }
    }

    public class CourseTests
    {
        [Fact]
        public void Course_Properties_CanBeSet()
        {
            var course = new Course
            {
                CourseID = 1050,
                Title = "Chemistry",
                Credits = 3,
                DepartmentID = 1,
                TeachingMaterialImagePath = "/uploads/img.jpg"
            };

            Assert.Equal(1050, course.CourseID);
            Assert.Equal("Chemistry", course.Title);
            Assert.Equal(3, course.Credits);
            Assert.Equal(1, course.DepartmentID);
            Assert.Equal("/uploads/img.jpg", course.TeachingMaterialImagePath);
        }
    }

    public class DepartmentTests
    {
        [Fact]
        public void Department_Properties_CanBeSet()
        {
            var dept = new Department
            {
                DepartmentID = 1,
                Name = "Engineering",
                Budget = 350000m,
                StartDate = new System.DateTime(2007, 9, 1),
                InstructorID = 5
            };

            Assert.Equal(1, dept.DepartmentID);
            Assert.Equal("Engineering", dept.Name);
            Assert.Equal(350000m, dept.Budget);
            Assert.Equal(new System.DateTime(2007, 9, 1), dept.StartDate);
            Assert.Equal(5, dept.InstructorID);
        }

        [Fact]
        public void Department_InstructorID_CanBeNull()
        {
            var dept = new Department { InstructorID = null };

            Assert.Null(dept.InstructorID);
        }
    }

    public class NotificationModelTests
    {
        [Fact]
        public void Notification_Properties_CanBeSet()
        {
            var n = new Notification
            {
                Id = 1,
                EntityType = "Student",
                EntityId = "42",
                Operation = "CREATE",
                Message = "New Student created",
                CreatedAt = new System.DateTime(2024, 1, 1, 12, 0, 0),
                CreatedBy = "Admin",
                IsRead = false,
                ReadAt = null
            };

            Assert.Equal(1, n.Id);
            Assert.Equal("Student", n.EntityType);
            Assert.Equal("42", n.EntityId);
            Assert.Equal("CREATE", n.Operation);
            Assert.Equal("New Student created", n.Message);
            Assert.False(n.IsRead);
            Assert.Null(n.ReadAt);
            Assert.Equal("Admin", n.CreatedBy);
        }
    }

    public class EntityOperationTests
    {
        [Fact]
        public void EntityOperation_HasExpectedValues()
        {
            Assert.Equal(0, (int)EntityOperation.CREATE);
            Assert.Equal(1, (int)EntityOperation.UPDATE);
            Assert.Equal(2, (int)EntityOperation.DELETE);
        }
    }
}

