+using System;
+using Xunit;
+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+
+namespace ContosoUniversity.Tests.Services
+{
+    public class NotificationServiceTests : IDisposable
+    {
+        private readonly NotificationService _sut;
+
+        public NotificationServiceTests()
+        {
+            _sut = new NotificationService();
+            // Drain static queue to isolate tests
+            while (_sut.ReceiveNotification() != null) { }
+        }
+
+        public void Dispose()
+        {
+            // Drain after test too
+            while (_sut.ReceiveNotification() != null) { }
+            _sut.Dispose();
+        }
+
+        [Fact]
+        public void SendNotification_WithDisplayName_EnqueuesWithCorrectMessage()
+        {
+            _sut.SendNotification("Student", "42", "John Smith", EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Student", notification!.EntityType);
+            Assert.Equal("42", notification.EntityId);
+            Assert.Equal("CREATE", notification.Operation);
+            Assert.Equal("New Student 'John Smith' has been created", notification.Message);
+            Assert.Equal("Admin", notification.CreatedBy);
+            Assert.False(notification.IsRead);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutDisplayName_UsesIdInMessage()
+        {
+            _sut.SendNotification("Course", "101", EntityOperation.UPDATE, "System");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Course (ID: 101) has been updated", notification!.Message);
+            Assert.Equal("UPDATE", notification.Operation);
+        }
+
+        [Fact]
+        public void SendNotification_WithoutUserName_DefaultsToSystem()
+        {
+            _sut.SendNotification("Department", "5", EntityOperation.DELETE);
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("System", notification!.CreatedBy);
+        }
+
+        [Theory]
+        [InlineData(EntityOperation.CREATE, "New Student 'Test' has been created")]
+        [InlineData(EntityOperation.UPDATE, "Student 'Test' has been updated")]
+        [InlineData(EntityOperation.DELETE, "Student 'Test' has been deleted")]
+        public void SendNotification_DifferentOperations_GeneratesCorrectMessages(EntityOperation op, string expectedMessage)
+        {
+            _sut.SendNotification("Student", "1", "Test", op, "User");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal(expectedMessage, notification!.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WithNullDisplayName_UsesIdFormat()
+        {
+            _sut.SendNotification("Student", "99", null, EntityOperation.CREATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("New Student (ID: 99) has been created", notification!.Message);
+        }
+
+        [Fact]
+        public void SendNotification_WithEmptyDisplayName_UsesIdFormat()
+        {
+            _sut.SendNotification("Student", "99", "   ", EntityOperation.UPDATE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Student (ID: 99) has been updated", notification!.Message);
+        }
+
+        [Fact]
+        public void ReceiveNotification_EmptyQueue_ReturnsNull()
+        {
+            var result = _sut.ReceiveNotification();
+
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void ReceiveNotification_MultipleItems_ReturnsFIFO()
+        {
+            _sut.SendNotification("A", "1", "First", EntityOperation.CREATE, "User");
+            _sut.SendNotification("B", "2", "Second", EntityOperation.UPDATE, "User");
+
+            var first = _sut.ReceiveNotification();
+            var second = _sut.ReceiveNotification();
+
+            Assert.Equal("A", first!.EntityType);
+            Assert.Equal("B", second!.EntityType);
+        }
+
+        [Fact]
+        public void ReceiveNotification_AfterAllConsumed_ReturnsNull()
+        {
+            _sut.SendNotification("X", "1", EntityOperation.CREATE);
+
+            _sut.ReceiveNotification(); // consume it
+            var result = _sut.ReceiveNotification();
+
+            Assert.Null(result);
+        }
+
+        [Fact]
+        public void MarkAsRead_DoesNotThrow()
+        {
+            // MarkAsRead is a no-op but should not throw
+            var exception = Record.Exception(() => _sut.MarkAsRead(42));
+
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_SetsCreatedAtToRecentTime()
+        {
+            var before = DateTime.Now.AddSeconds(-1);
+            _sut.SendNotification("Test", "1", EntityOperation.CREATE);
+            var after = DateTime.Now.AddSeconds(1);
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.InRange(notification!.CreatedAt, before, after);
+        }
+
+        [Fact]
+        public void Dispose_DoesNotThrow()
+        {
+            var service = new NotificationService();
+
+            var exception = Record.Exception(() => service.Dispose());
+
+            Assert.Null(exception);
+        }
+
+        [Fact]
+        public void SendNotification_TwoArgOverload_SetsEntityIdAndOperation()
+        {
+            _sut.SendNotification("Instructor", "7", EntityOperation.DELETE, "Admin");
+
+            var notification = _sut.ReceiveNotification();
+
+            Assert.NotNull(notification);
+            Assert.Equal("Instructor", notification!.EntityType);
+            Assert.Equal("7", notification.EntityId);
+            Assert.Equal("DELETE", notification.Operation);
+            Assert.Contains("Instructor (ID: 7)", notification.Message);
+            Assert.Contains("deleted", notification.Message);
+        }
+    }
+}
