using System;
using System.Linq;
using Xunit;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.EntityFrameworkCore;

namespace ContosoUniversity.Tests.Data
{
    public class DbInitializerTests
    {
        [Fact]
        public void Initialize_EmptyDatabase_SeedsStudents()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.Students.Count());
            Assert.Contains(context.Students, s => s.LastName == "Alexander" && s.FirstMidName == "Carson");
            Assert.Contains(context.Students, s => s.LastName == "Olivetto" && s.FirstMidName == "Nino");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsInstructors()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(5, context.Instructors.Count());
            Assert.Contains(context.Instructors, i => i.LastName == "Abercrombie");
            Assert.Contains(context.Instructors, i => i.LastName == "Zheng");
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsDepartments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(4, context.Departments.Count());
            var engineering = context.Departments.Single(d => d.Name == "Engineering");
            Assert.Equal(350000, engineering.Budget);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourses()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(7, context.Courses.Count());
            var chemistry = context.Courses.Single(c => c.Title == "Chemistry");
            Assert.Equal(1050, chemistry.CourseID);
            Assert.Equal(3, chemistry.Credits);
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(3, context.OfficeAssignments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsCourseAssignments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(8, context.CourseAssignments.Count());
        }

        [Fact]
        public void Initialize_EmptyDatabase_SeedsEnrollments()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            Assert.Equal(11, context.Enrollments.Count());
            // Verify a specific enrollment
            var alexChemistry = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .FirstOrDefault(e => e.Student.LastName == "Alexander" && e.Course.Title == "Chemistry");
            Assert.NotNull(alexChemistry);
            Assert.Equal(Grade.A, alexChemistry!.Grade);
        }

        [Fact]
        public void Initialize_AlreadySeeded_DoesNotDuplicateData()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);
            var initialStudentCount = context.Students.Count();
            var initialCourseCount = context.Courses.Count();

            // Run again
            DbInitializer.Initialize(context);

            Assert.Equal(initialStudentCount, context.Students.Count());
            Assert.Equal(initialCourseCount, context.Courses.Count());
        }

        [Fact]
        public void Initialize_SeedsEnrollmentWithNullGrade()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            // Arturo Anand's Chemistry enrollment has no grade
            var anandChemistry = context.Enrollments
                .Include(e => e.Student)
                .Include(e => e.Course)
                .FirstOrDefault(e => e.Student.LastName == "Anand" && e.Course.Title == "Chemistry");
            Assert.NotNull(anandChemistry);
            Assert.Null(anandChemistry!.Grade);
        }

        [Fact]
        public void Initialize_DepartmentsLinkedToInstructors()
        {
            using var context = TestDbContextFactory.Create();

            DbInitializer.Initialize(context);

            var english = context.Departments
                .Include(d => d.Administrator)
                .Single(d => d.Name == "English");
            Assert.NotNull(english.Administrator);
            Assert.Equal("Abercrombie", english.Administrator!.LastName);
        }
    }

    public class SchoolContextTests
    {
        [Fact]
        public void SchoolContext_CanCreateWithInMemoryProvider()
        {
            using var context = TestDbContextFactory.Create();

            Assert.NotNull(context.Students);
            Assert.NotNull(context.Courses);
            Assert.NotNull(context.Departments);
            Assert.NotNull(context.Enrollments);
            Assert.NotNull(context.Instructors);
            Assert.NotNull(context.OfficeAssignments);
            Assert.NotNull(context.CourseAssignments);
            Assert.NotNull(context.People);
            Assert.NotNull(context.Notifications);
        }

        [Fact]
        public void SchoolContext_CanAddAndRetrieveStudent()
        {
            using var context = TestDbContextFactory.Create();
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "Student",
                EnrollmentDate = new DateTime(2024, 1, 1)
            };

            context.Students.Add(student);
            context.SaveChanges();

            var retrieved = context.Students.Single();
            Assert.Equal("Test", retrieved.FirstMidName);
            Assert.Equal("Student", retrieved.LastName);
            Assert.Equal(new DateTime(2024, 1, 1), retrieved.EnrollmentDate);
            Assert.True(retrieved.ID > 0);
        }

        [Fact]
        public void SchoolContext_CourseAssignment_HasCompositeKey()
        {
            using var context = TestDbContextFactory.Create();
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            context.Instructors.Add(instructor);
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 1000,
                StartDate = DateTime.Now
            };
            context.Departments.Add(dept);
            context.SaveChanges();

            var course = new Course
            {
                CourseID = 9999,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            context.Courses.Add(course);
            context.SaveChanges();

            var assignment = new CourseAssignment
            {
                CourseID = course.CourseID,
                InstructorID = instructor.ID
            };
            context.CourseAssignments.Add(assignment);
            context.SaveChanges();

            var retrieved = context.CourseAssignments
                .Single(ca => ca.CourseID == 9999 && ca.InstructorID == instructor.ID);
            Assert.NotNull(retrieved);
        }

        [Fact]
        public void SchoolContext_TPH_StudentAndInstructorSharePersonTable()
        {
            using var context = TestDbContextFactory.Create();
            context.Students.Add(new Student
            {
                FirstMidName = "Stu",
                LastName = "Dent",
                EnrollmentDate = DateTime.Now
            });
            context.Instructors.Add(new Instructor
            {
                FirstMidName = "Ins",
                LastName = "Tructor",
                HireDate = DateTime.Now,
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            });
            context.SaveChanges();

            // Both should be in People
            Assert.Equal(2, context.People.Count());
            Assert.Single(context.Students);
            Assert.Single(context.Instructors);
        }
    }
}

