using System;
using System.Linq;
using System.Net;
using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student SeedStudent(string first = "John", string last = "Doe", DateTime? enrollmentDate = null)
        {
            var student = new Student
            {
                FirstMidName = first,
                LastName = last,
                EnrollmentDate = enrollmentDate ?? new DateTime(2020, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        private void SeedMultipleStudents()
        {
            _context.Students.AddRange(
                new Student { FirstMidName = "Alice", LastName = "Anderson", EnrollmentDate = new DateTime(2020, 1, 1) },
                new Student { FirstMidName = "Bob", LastName = "Baker", EnrollmentDate = new DateTime(2021, 1, 1) },
                new Student { FirstMidName = "Charlie", LastName = "Clark", EnrollmentDate = new DateTime(2019, 1, 1) },
                new Student { FirstMidName = "Diana", LastName = "Davis", EnrollmentDate = new DateTime(2022, 1, 1) }
            );
            _context.SaveChanges();
        }

        // --- Index tests ---

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudentsOrderedByLastName()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal(4, model.Count);
            // Default sort = by LastName ascending
            Assert.Equal("Anderson", model[0].LastName);
            Assert.Equal("Baker", model[1].LastName);
            Assert.Equal("Clark", model[2].LastName);
            Assert.Equal("Davis", model[3].LastName);
        }

        [Fact]
        public void Index_SortByNameDesc_ReverseOrder()
        {
            SeedMultipleStudents();

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Davis", model[0].LastName);
            Assert.Equal("Anderson", model[3].LastName);
        }

        [Fact]
        public void Index_SortByDate_OrdersByEnrollmentDate()
        {
            SeedMultipleStudents();

            var result = _controller.Index("Date", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Clark", model[0].LastName);    // 2019
            Assert.Equal("Anderson", model[1].LastName);  // 2020
        }

        [Fact]
        public void Index_SortByDateDesc_OrdersByEnrollmentDateDescending()
        {
            SeedMultipleStudents();

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal("Davis", model[0].LastName);     // 2022
            Assert.Equal("Clark", model[3].LastName);     // 2019
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, null, "Baker", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Baker", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, null, "Alice", null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Anderson", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_ResetsPage()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, null, "Anderson", 5) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            // When searchString is provided, page resets to 1
            Assert.Equal(1, model.PageIndex);
        }

        [Fact]
        public void Index_NullSearchWithCurrentFilter_UsesCurrentFilter()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, "Clark", null, null) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Clark", model[0].LastName);
        }

        [Fact]
        public void Index_SetsViewBagSortParameters()
        {
            SeedMultipleStudents();

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_WithSortOrder_SetsViewBagCorrectly()
        {
            SeedMultipleStudents();

            _controller.Index("Date", null, null, null);

            Assert.Equal("", _controller.ViewBag.NameSortParm);
            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_Pagination_ReturnsCorrectPage()
        {
            // Seed 15 students to test pagination (pageSize=10)
            for (int i = 0; i < 15; i++)
            {
                SeedStudent($"First{i:D2}", $"Last{i:D2}", new DateTime(2020, 1, 1));
            }

            var result = _controller.Index(null, null, null, 2) as ViewResult;

            var model = Assert.IsType<PaginatedList<Student>>(result!.Model);
            Assert.Equal(5, model.Count); // remaining 5 on page 2
            Assert.Equal(2, model.PageIndex);
        }

        // --- Details tests ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Jane", "Doe");

            var result = _controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result!.Model);
            Assert.Equal("Doe", model.LastName);
            Assert.Equal("Jane", model.FirstMidName);
        }

        // --- Create GET ---

        [Fact]
        public void CreateGet_ReturnsViewWithStudentWithTodaysDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result!.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        // --- Create POST ---

        [Fact]
        public void CreatePost_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = new DateTime(2024, 9, 1)
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
            Assert.Equal("New", _context.Students.First().FirstMidName);
        }

        [Fact]
        public void CreatePost_DefaultEnrollmentDate_ReturnsViewWithModelError()
        {
            var student = new Student
            {
                FirstMidName = "Bad",
                LastName = "Date",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void CreatePost_DateTooEarly_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "Old",
                LastName = "Person",
                EnrollmentDate = new DateTime(1752, 12, 31)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void CreatePost_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "Test",
                LastName = "",
                EnrollmentDate = new DateTime(2024, 1, 1)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Students);
        }

        // --- Edit GET ---

        [Fact]
        public void EditGet_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void EditGet_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void EditGet_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Edit", "Me");

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result!.Model);
            Assert.Equal("Me", model.LastName);
        }

        // --- Edit POST ---

        [Fact]
        public void EditPost_ValidStudent_RedirectsToIndex()
        {
            var student = SeedStudent("Before", "Edit");
            // Detach so EF doesn't track stale entity
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updatedStudent = new Student
            {
                ID = student.ID,
                FirstMidName = "After",
                LastName = "Edit",
                EnrollmentDate = new DateTime(2024, 9, 1)
            };

            var result = _controller.Edit(updatedStudent);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void EditPost_DefaultEnrollmentDate_ReturnsViewWithError()
        {
            var student = SeedStudent();

            var editStudent = new Student
            {
                ID = student.ID,
                FirstMidName = "Test",
                LastName = "Person",
                EnrollmentDate = default
            };

            var result = _controller.Edit(editStudent) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        // --- Delete GET ---

        [Fact]
        public void DeleteGet_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void DeleteGet_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteGet_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Delete", "Me");

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result!.Model);
            Assert.Equal("Me", model.LastName);
        }

        // --- Delete POST ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesStudentAndRedirects()
        {
            var student = SeedStudent("Bye", "Student");

            var result = _controller.DeleteConfirmed(student.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Students);
        }
    }
}

