using System;
using System.IO;
using System.Linq;
using System.Net;
using Xunit;
using Moq;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly CoursesController _controller;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();
            _tempDir = Path.Combine(Path.GetTempPath(), "CoursesTest_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);
            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
            {
                try { Directory.Delete(_tempDir, true); } catch { }
            }
        }

        private Department SeedDepartment()
        {
            var dept = new Department
            {
                Name = "TestDept",
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(Department? dept = null)
        {
            dept ??= SeedDepartment();
            var course = new Course
            {
                CourseID = 1001,
                Title = "Test Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var dept = SeedDepartment();
            SeedCourse(dept);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Test Course", model[0].Title);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = SeedCourse();

            var result = _controller.Details(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result!.Model);
            Assert.Equal("Test Course", model.Title);
            Assert.Equal(3, model.Credits);
        }

        // --- Create GET ---

        [Fact]
        public void CreateGet_ReturnsViewWithDepartmentList()
        {
            SeedDepartment();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        // --- Create POST ---

        [Fact]
        public void CreatePost_ValidCourse_NoImage_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2001,
                Title = "New Course",
                Credits = 4,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void CreatePost_WithValidImage_SavesFileAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2002,
                Title = "Course With Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var savedCourse = _context.Courses.Single();
            Assert.NotNull(savedCourse.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", savedCourse.TeachingMaterialImagePath);
        }

        [Fact]
        public void CreatePost_InvalidExtension_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2003,
                Title = "Bad Ext",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("malware.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("valid image file", _controller.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage);
        }

        [Fact]
        public void CreatePost_FileTooLarge_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 2004,
                Title = "Big File",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.png");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024); // 6MB > 5MB limit

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
            Assert.Contains("5MB", _controller.ModelState["teachingMaterialImage"]!.Errors[0].ErrorMessage);
        }

        [Fact]
        public void CreatePost_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 2005, Title = "" };

            var result = _controller.Create(course, null!) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Courses);
        }

        [Theory]
        [InlineData(".jpg")]
        [InlineData(".jpeg")]
        [InlineData(".png")]
        [InlineData(".gif")]
        [InlineData(".bmp")]
        public void CreatePost_AllowedExtensions_AcceptsUpload(string ext)
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3000 + ext.GetHashCode(),
                Title = $"Course{ext}",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns($"image{ext}");
            mockFile.Setup(f => f.Length).Returns(512);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);

            Assert.IsType<RedirectToActionResult>(result);
        }

        // --- Edit GET ---

        [Fact]
        public void EditGet_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void EditGet_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(99999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void EditGet_ValidId_ReturnsViewWithCourse()
        {
            var course = SeedCourse();

            var result = _controller.Edit(course.CourseID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result!.Model);
            Assert.Equal("Test Course", model.Title);
        }

        // --- Edit POST ---

        [Fact]
        public void EditPost_ValidCourse_NoImage_RedirectsToIndex()
        {
            var course = SeedCourse();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updatedCourse = new Course
            {
                CourseID = course.CourseID,
                Title = "Updated Course",
                Credits = 4,
                DepartmentID = course.DepartmentID
            };

            var result = _controller.Edit(updatedCourse, null!);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void EditPost_InvalidExtension_ReturnsViewWithError()
        {
            var course = SeedCourse();
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("bad.txt");
            mockFile.Setup(f => f.Length).Returns(100);

            var result = _controller.Edit(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
