using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class DepartmentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly DepartmentsController _controller;

        public DepartmentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new DepartmentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Instructor SeedInstructor()
        {
            var instructor = new Instructor
            {
                FirstMidName = "Test",
                LastName = "Instructor",
                HireDate = new DateTime(2000, 1, 1),
                CourseAssignments = new System.Collections.Generic.List<CourseAssignment>()
            };
            _context.Instructors.Add(instructor);
            _context.SaveChanges();
            return instructor;
        }

        private Department SeedDepartment(Instructor? instructor = null)
        {
            instructor ??= SeedInstructor();
            var dept = new Department
            {
                Name = "Test Dept",
                Budget = 200000,
                StartDate = new DateTime(2020, 1, 1),
                InstructorID = instructor.ID
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        // --- Index ---

        [Fact]
        public void Index_ReturnsViewWithDepartments()
        {
            SeedDepartment();

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result!.Model);
            Assert.Single(model);
            Assert.Equal("Test Dept", model[0].Name);
        }

        [Fact]
        public void Index_MultipleDepartments_ReturnsAll()
        {
            var inst = SeedInstructor();
            _context.Departments.AddRange(
                new Department { Name = "Dept A", Budget = 100, StartDate = DateTime.Now, InstructorID = inst.ID },
                new Department { Name = "Dept B", Budget = 200, StartDate = DateTime.Now, InstructorID = inst.ID }
            );
            _context.SaveChanges();

            var result = _controller.Index() as ViewResult;

            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Department>>(result!.Model);
            Assert.Equal(2, model.Count);
        }

        // --- Details ---

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void Details_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Details(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithDepartment()
        {
            var dept = SeedDepartment();

            var result = _controller.Details(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result!.Model);
            Assert.Equal("Test Dept", model.Name);
            Assert.Equal(200000, model.Budget);
        }

        // --- Create GET ---

        [Fact]
        public void CreateGet_ReturnsViewWithInstructorList()
        {
            SeedInstructor();

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.InstructorID);
        }

        // --- Create POST ---

        [Fact]
        public void CreatePost_ValidDepartment_RedirectsToIndex()
        {
            var instructor = SeedInstructor();
            var dept = new Department
            {
                Name = "New Dept",
                Budget = 50000,
                StartDate = new DateTime(2024, 1, 1),
                InstructorID = instructor.ID
            };

            var result = _controller.Create(dept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Departments);
            Assert.Equal("New Dept", _context.Departments.First().Name);
        }

        [Fact]
        public void CreatePost_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department();

            var result = _controller.Create(dept) as ViewResult;

            Assert.NotNull(result);
            Assert.Empty(_context.Departments);
        }

        // --- Edit GET ---

        [Fact]
        public void EditGet_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit((int?)null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void EditGet_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void EditGet_ValidId_ReturnsViewWithDepartment()
        {
            var dept = SeedDepartment();

            var result = _controller.Edit(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result!.Model);
            Assert.Equal("Test Dept", model.Name);
        }

        // --- Edit POST ---

        [Fact]
        public void EditPost_ValidDepartment_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            _context.Entry(dept).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updatedDept = new Department
            {
                DepartmentID = dept.DepartmentID,
                Name = "Updated Dept",
                Budget = 300000,
                StartDate = new DateTime(2024, 6, 1),
                InstructorID = dept.InstructorID
            };

            var result = _controller.Edit(updatedDept);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void EditPost_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Name", "Required");
            var dept = new Department { DepartmentID = 1 };

            var result = _controller.Edit(dept) as ViewResult;

            Assert.NotNull(result);
        }

        // --- Delete GET ---

        [Fact]
        public void DeleteGet_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal((int)HttpStatusCode.BadRequest, statusResult.StatusCode);
        }

        [Fact]
        public void DeleteGet_NonExistentId_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void DeleteGet_ValidId_ReturnsViewWithDepartment()
        {
            var dept = SeedDepartment();

            var result = _controller.Delete(dept.DepartmentID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Department>(result!.Model);
            Assert.Equal("Test Dept", model.Name);
        }

        // --- Delete POST ---

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesDepartmentAndRedirects()
        {
            var dept = SeedDepartment();

            var result = _controller.DeleteConfirmed(dept.DepartmentID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Departments);
        }
    }
}

