using System;
using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;

namespace ContosoUniversity.Tests.Controllers
{
    public class NotificationsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly NotificationsController _controller;

        public NotificationsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new NotificationsController(_context);
            // Drain static queue to isolate tests
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            // Drain queue after each test
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void GetNotifications_NoNotifications_ReturnsEmptyList()
        {
            var result = _controller.GetNotifications();

            Assert.NotNull(result);
            var jsonResult = Assert.IsType<JsonResult>(result);
            Assert.NotNull(jsonResult.Value);

            // Access the anonymous type via dynamic
            dynamic value = jsonResult.Value!;
            Assert.True((bool)value.success);
            Assert.Equal(0, (int)value.count);
        }

        [Fact]
        public void GetNotifications_WithNotifications_ReturnsUpTo10()
        {
            // Enqueue notifications via the shared static queue
            var svc = new NotificationService();
            for (int i = 0; i < 15; i++)
            {
                svc.SendNotification("Test", i.ToString(), $"Item{i}", EntityOperation.CREATE, "Admin");
            }

            var result = _controller.GetNotifications();
            var jsonResult = Assert.IsType<JsonResult>(result);
            dynamic value = jsonResult.Value!;

            Assert.True((bool)value.success);
            Assert.Equal(10, (int)value.count); // Limited to 10
        }

        [Fact]
        public void GetNotifications_WithFewNotifications_ReturnsAll()
        {
            var svc = new NotificationService();
            svc.SendNotification("Student", "1", "Alice", EntityOperation.CREATE, "Admin");
            svc.SendNotification("Course", "2", "Math", EntityOperation.UPDATE, "Admin");

            var result = _controller.GetNotifications();
            var jsonResult = Assert.IsType<JsonResult>(result);
            dynamic value = jsonResult.Value!;

            Assert.True((bool)value.success);
            Assert.Equal(2, (int)value.count);
        }

        [Fact]
        public void MarkAsRead_ReturnsSuccess()
        {
            var result = _controller.MarkAsRead(42);

            var jsonResult = Assert.IsType<JsonResult>(result);
            dynamic value = jsonResult.Value!;
            Assert.True((bool)value.success);
        }

        [Fact]
        public void Index_ReturnsView()
        {
            var result = _controller.Index();

            Assert.IsType<ViewResult>(result);
        }

        [Fact]
        public void GetNotifications_ConsumesFromQueue_SecondCallGetsLess()
        {
            var svc = new NotificationService();
            for (int i = 0; i < 5; i++)
            {
                svc.SendNotification("X", i.ToString(), EntityOperation.CREATE);
            }

            // First call consumes up to 10 (gets 5)
            var result1 = _controller.GetNotifications();
            var json1 = (JsonResult)result1;
            dynamic v1 = json1.Value!;
            Assert.Equal(5, (int)v1.count);

            // Second call - queue should be empty
            var result2 = _controller.GetNotifications();
            var json2 = (JsonResult)result2;
            dynamic v2 = json2.Value!;
            Assert.Equal(0, (int)v2.count);
        }
    }
}

