using System;
using Xunit;
using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Services;
using ContosoUniversity.Tests.Helpers;

namespace ContosoUniversity.Tests.Controllers
{
    public class BaseControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly TestableBaseController _controller;

        // Concrete class to test BaseController (which is abstract)
        private class TestableBaseController : BaseController
        {
            public TestableBaseController(SchoolContext context) : base(context) { }

            public void TestSendNotification3Args(string entityType, string entityId, EntityOperation operation)
            {
                SendEntityNotification(entityType, entityId, operation);
            }

            public void TestSendNotification4Args(string entityType, string entityId, string displayName, EntityOperation operation)
            {
                SendEntityNotification(entityType, entityId, displayName, operation);
            }

            public NotificationService GetNotificationService() => notificationService;
            public SchoolContext GetDb() => db;
        }

        public BaseControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new TestableBaseController(_context);
            // Drain static queue
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
        }

        public void Dispose()
        {
            var svc = new NotificationService();
            while (svc.ReceiveNotification() != null) { }
            _controller.Dispose();
            _context.Dispose();
        }

        [Fact]
        public void Constructor_SetsDbContext()
        {
            Assert.Same(_context, _controller.GetDb());
        }

        [Fact]
        public void Constructor_InitializesNotificationService()
        {
            Assert.NotNull(_controller.GetNotificationService());
        }

        [Fact]
        public void SendEntityNotification_3Args_EnqueuesNotification()
        {
            _controller.TestSendNotification3Args("Student", "42", EntityOperation.CREATE);

            var notification = _controller.GetNotificationService().ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Student", notification!.EntityType);
            Assert.Equal("42", notification.EntityId);
            Assert.Contains("Student (ID: 42)", notification.Message);
            Assert.Contains("created", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_4Args_EnqueuesNotificationWithDisplayName()
        {
            _controller.TestSendNotification4Args("Course", "101", "Chemistry", EntityOperation.UPDATE);

            var notification = _controller.GetNotificationService().ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("Course", notification!.EntityType);
            Assert.Equal("101", notification.EntityId);
            Assert.Contains("Chemistry", notification.Message);
            Assert.Contains("updated", notification.Message);
        }

        [Fact]
        public void SendEntityNotification_SetsUserNameToSystem()
        {
            _controller.TestSendNotification3Args("Test", "1", EntityOperation.DELETE);

            var notification = _controller.GetNotificationService().ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Equal("System", notification!.CreatedBy);
        }

        [Fact]
        public void Dispose_DisposesDbAndNotificationService()
        {
            var controller = new TestableBaseController(TestDbContextFactory.Create());

            var exception = Record.Exception(() => controller.Dispose());

            Assert.Null(exception);
        }

        [Theory]
        [InlineData(EntityOperation.CREATE, "created")]
        [InlineData(EntityOperation.UPDATE, "updated")]
        [InlineData(EntityOperation.DELETE, "deleted")]
        public void SendEntityNotification_AllOperations_GeneratesCorrectVerb(EntityOperation op, string verb)
        {
            _controller.TestSendNotification3Args("Entity", "1", op);

            var notification = _controller.GetNotificationService().ReceiveNotification();
            Assert.NotNull(notification);
            Assert.Contains(verb, notification!.Message);
        }
    }
}

